    },
    {
      "document_id": "135577",
      "explanation": "Reasoned disagreement over whether the legislation would be improved by a new clause and amendment; 'trying to have it both ways' is ordinary parliamentary criticism without emotional charge.",
      "label": "0"
    },
    {
      "document_id": "958100",
      "explanation": "A brief courteous undertaking to pass a constituent's UKVI problem to the Home Secretary. Purely procedural.",
