    {
      "document_id": "766443",
      "explanation": "Criticises consultation practice as 'communication not consultation'. A rhetorical contrast and mild complaint, but expressed as a definitional/policy critique without emotionally loaded framing.",
      "label": "0"
    },
    {
      "document_id": "152514",
      "explanation": "Reports constituent opposition to identity cards and raises practical questions about verification machines and costs. Reasoned concern plus technical queries; no emotional appeal.",
