    },
    {
      "document_id": "157764",
      "explanation": "A question about early debt advice and the viability of citizens advice bureaus. Expresses concern in measured terms without vivid suffering or emotional appeal.",
      "label": "0"
    },
    {
      "document_id": "168114",
      "explanation": "A one-line factual question asking how many Iraqi personnel have been trained by UK and coalition forces. Matches the negative example of a neutral factual question.",
